{"content":"import re


def answer(question):
    """Evaluate a verbal arithmetic expression from left to right."""
    if not isinstance(question, str) or not question.startswith("What is "):
        raise ValueError("unknown operation")
    if not question.endswith("?"):
        raise ValueError("syntax error")

    tokens = question[len("What is "):-1].split()
    words = {"plus", "minus", "multiplied", "divided", "by"}

    def is_number(token):
        return re.fullmatch(r"-?[0-9]+", token) is not None

    if any(token not in words and not is_number(token) for token in tokens):
        raise ValueError("unknown operation")
    if not tokens or not is_number(tokens[0]):
        raise ValueError("syntax error")

    result = int(tokens[0])
    index = 1
    while index < len(tokens):
        operation = tokens[index]
        index += 1
        if operation in {"multiplied", "divided"}:
            if index >= len(tokens) or tokens[index] != "by":
                raise ValueError("syntax error")
            index += 1
        elif operation not in {"plus", "minus"}:
            raise ValueError("syntax error")

        if index >= len(tokens) or not is_number(tokens[index]):
            raise ValueError("syntax error")
        operand = int(tokens[index])
        index += 1

        if operation == "plus":
            result += operand
        elif operation == "minus":
            result -= operand
        elif operation == "multiplied":
            result *= operand
        else:
            if operand == 0:
                raise ValueError("syntax error")
            result //= operand

    return result
